for i in "${!NUID[@]}"; do   
    study="${studies[$i]}"
    echo "${study}"
    
    for ID in ${NUID[$i]}; do 
        esearch -db nucleotide -query "$ID" |efetch -format gb > "${path}""${study}"/nucl/"$ID".gb
        cat "${path}""${study}"/nucl/"$ID".gb >> "${path}""${study}"/sequences_"${study}".gb
        rm "${path}""${study}"/nucl/"$ID".gb >/dev/null
    done
done

